import json, glob, os
print("=== ACTIVE FACTORS (json without .bak) ===")
for fp in sorted(glob.glob('factors/*.json')):
    if os.path.exists(fp + '.bak'):
        continue
    d = json.load(open(fp))
    # find ic / icir anywhere
    def find(d, keys):
        if isinstance(d, dict):
            for k in keys:
                if k in d:
                    return d[k]
            for v in d.values():
                r = find(v, keys)
                if r is not None:
                    return r
        return None
    ic = find(d, ['ic','IC','mean_ic','pearson_ic'])
    icir = find(d, ['icir','ICIR','mean_icir'])
    q = abs(ic)*abs(icir) if (ic is not None and icir is not None) else None
    cat = d.get('category') or (d.get('meta') or {}).get('category') or '?'
    print(f"{os.path.basename(fp):40s} ic={ic}  icir={icir}  q={q:.5f}" if q else f"{os.path.basename(fp):40s} ic={ic}  icir={icir}  cat={cat}")
EOF

